const incoming = $input.first().json;
const trigger = incoming.body ?? incoming;
const headers = incoming.headers ?? {};
const automationSecret = headers['x-automation-secret'] || headers['X-Automation-Secret'] || '';

const contextUrl = trigger.app?.contextUrl ?? '';
const callbackUrl = trigger.app?.callbackUrl ?? '';
const jobUrl = trigger.job?.url ?? '';

if (!/^https?:\/\//.test(contextUrl)) {
  throw new Error('Invalid context URL in webhook payload');
}

if (!/^https?:\/\//.test(callbackUrl)) {
  throw new Error('Invalid callback URL in webhook payload');
}

if (!/^https?:\/\//.test(jobUrl)) {
  throw new Error('Invalid job URL in webhook payload');
}

if (!automationSecret) {
  throw new Error('Missing automation secret header on webhook request');
}

return [{
  json: {
    reason: trigger.reason ?? 'queued',
    run: trigger.run ?? {},
    job: trigger.job ?? {},
    profile: trigger.profile ?? {},
    app: trigger.app ?? {},
    contextUrl,
    callbackUrl,
    jobUrl,
    automationSecret,
  },
}];

const source = $('Prepare Anchor Task').item.json || {};
const session = $('Anchor Create Session').item.json || {};
const task = $input.first().json || {};
const workflowId = task.data?.workflow_id || task.workflow_id || task.id || task.data?.id || '';
if (!workflowId) {
  throw new Error('Anchor did not return workflow_id for perform-web-task');
}

return [{
  json: {
    ...source,
    pollAttempt: 0,
    anchor: {
      sessionId: session.sessionId || session.id || session.data?.id || '',
      liveViewUrl: session.liveViewUrl || session.live_view_url || session.data?.live_view_url || '',
      cdpUrl: session.cdpUrl || session.cdp_url || session.data?.cdp_url || '',
      workflowId,
      taskStatus: task.data?.status || task.status || 'RUNNING',
      raw: task,
    },
  },
}];

const state = $('Wait Before Status Check').item.json || {};
const envelope = $input.first().json || {};
const taskStatus = envelope.data?.status || envelope.status || 'UNKNOWN';
const pollAttempt = Number(state.pollAttempt || 0) + 1;
const maxPollAttempts = Number(state.maxPollAttempts || 8);

return [{
  json: {
    ...state,
    pollAttempt,
    exhausted: taskStatus === 'RUNNING' && pollAttempt >= maxPollAttempts,
    shouldPoll: taskStatus === 'RUNNING' && pollAttempt < maxPollAttempts,
    anchorResult: envelope.data?.result ?? envelope.result ?? null,
    anchor: {
      ...(state.anchor || {}),
      taskStatus,
      raw: envelope,
    },
  },
}];

const state = $('Evaluate Task Status').item.json || {};
const recordingsEnvelope = $input.first().json || {};
const status = state.anchor?.taskStatus || 'UNKNOWN';
const raw = state.anchor?.raw;
const result = state.anchorResult;

function extractRecordingUrls(input) {
  const queue = [input];
  const urls = [];
  while (queue.length) {
    const value = queue.shift();
    if (!value) continue;
    if (typeof value === 'string') {
      if (/^https?:\/\//i.test(value)) urls.push(value);
      continue;
    }
    if (Array.isArray(value)) {
      queue.push(...value);
      continue;
    }
    if (typeof value === 'object') {
      for (const [key, nested] of Object.entries(value)) {
        if ((key.toLowerCase().includes('url') || key.toLowerCase().includes('recording')) && typeof nested === 'string' && /^https?:\/\//i.test(nested)) {
          urls.push(nested);
        } else {
          queue.push(nested);
        }
      }
    }
  }
  return Array.from(new Set(urls));
}

const recordings = extractRecordingUrls(recordingsEnvelope);
const anchorPayload = {
  sessionId: state.anchor?.sessionId,
  workflowId: state.anchor?.workflowId,
  liveViewUrl: state.anchor?.liveViewUrl,
  cdpUrl: state.anchor?.cdpUrl,
  taskStatus: status,
  recordings,
  raw,
};

const serialized = JSON.stringify({ raw, result }).toLowerCase();
const keywordNeedsInput = /(captcha|human verification|verify you are human|otp|two-factor|2fa|login|sign in|authorization|work authorization|resume upload|upload.*resume|required file|manual attention)/i;
const extractedError = typeof raw?.error === 'string'
  ? raw.error
  : raw?.error?.message || raw?.data?.error || raw?.message || null;

let finalPayload;
let parsed = result;
if (typeof parsed === 'string') {
  try { parsed = JSON.parse(parsed); } catch {}
}

if (status === 'FAILED') {
  finalPayload = {
    status: 'FAILED',
    currentStep: 'Automation failed',
    lastError: extractedError || 'Anchor reported a failed browser task.',
    message: extractedError || 'Anchor reported a failed browser task.',
    level: 'ERROR',
    payload: { anchor: anchorPayload },
  };
} else if (status === 'RUNNING') {
  finalPayload = {
    status: 'NEEDS_INPUT',
    needsInput: true,
    currentStep: 'Browser task still running',
    blockingQuestion: 'Anchor is still running after multiple checks. Open the live view or recording to inspect what is blocking the application.',
    inputField: 'manual_review',
    message: 'Anchor is still running after the configured wait window.',
    level: 'WARN',
    payload: { anchor: anchorPayload },
  };
} else if ((parsed && (parsed.status === 'submitted' || parsed.status === 'success')) || /submitted successfully/.test(serialized)) {
  finalPayload = {
    status: 'SUBMITTED',
    currentStep: 'Application submitted',
    message: parsed?.message || 'Application submitted successfully.',
    payload: { anchor: anchorPayload },
  };
} else if ((parsed && parsed.status === 'needs_input') || keywordNeedsInput.test(serialized)) {
  const inferredInputField = parsed?.inputField || (serialized.includes('resume') ? 'resume_upload' : serialized.includes('captcha') || serialized.includes('human verification') ? 'human_verification' : serialized.includes('login') || serialized.includes('sign in') ? 'login' : serialized.includes('authorization') ? 'work_authorization' : 'manual_review');
  finalPayload = {
    status: 'NEEDS_INPUT',
    needsInput: true,
    currentStep: 'Waiting for user attention',
    blockingQuestion: parsed?.blockingQuestion || parsed?.message || 'This application needs manual attention to continue.',
    inputField: inferredInputField,
    message: parsed?.message || 'Manual attention is required to continue this application.',
    level: 'WARN',
    payload: { anchor: anchorPayload },
  };
} else {
  finalPayload = {
    status: 'FAILED',
    currentStep: 'Automation failed',
    lastError: extractedError || parsed?.message || 'The browser tool could not complete the application.',
    message: parsed?.message || extractedError || 'Automation could not complete the application.',
    level: 'ERROR',
    payload: { anchor: anchorPayload },
  };
}

return [{ json: { finalPayload } }];
